package android.view;
public class KeyEvent {
 public static final int ACTION_DOWN=0,ACTION_UP=1,KEYCODE_BUTTON_A=96,KEYCODE_BUTTON_B=97,KEYCODE_BUTTON_X=99,KEYCODE_BUTTON_Y=100,KEYCODE_BUTTON_L1=102,KEYCODE_BUTTON_R1=103,KEYCODE_BUTTON_L2=104,KEYCODE_BUTTON_R2=105,KEYCODE_BUTTON_THUMBL=106,KEYCODE_BUTTON_THUMBR=107,KEYCODE_BUTTON_START=108,KEYCODE_DPAD_UP=19,KEYCODE_DPAD_DOWN=20,KEYCODE_DPAD_LEFT=21,KEYCODE_DPAD_RIGHT=22,KEYCODE_DPAD_CENTER=23,KEYCODE_ENTER=66,KEYCODE_BACK=4,KEYCODE_ESCAPE=111,KEYCODE_A=29,KEYCODE_D=32,KEYCODE_VOLUME_UP=24,KEYCODE_VOLUME_DOWN=25,KEYCODE_POWER=26,KEYCODE_W=51,KEYCODE_S=47,KEYCODE_CTRL_LEFT=113,KEYCODE_CTRL_RIGHT=114,KEYCODE_BUTTON_SELECT=109,KEYCODE_BUTTON_MODE=110;
 final int key,action,repeat,source;public KeyEvent(int k,boolean down,int r){this(k,down,r,InputDevice.SOURCE_GAMEPAD);}public KeyEvent(int k,boolean down,int r,int s){key=k;action=down?0:1;repeat=r;source=s;}public int getKeyCode(){return key;}public int getAction(){return action;}public int getRepeatCount(){return repeat;}public int getDeviceId(){return 0;}public int getSource(){return source;}public static String keyCodeToString(int k){try{for(java.lang.reflect.Field f:KeyEvent.class.getFields())if(f.getName().startsWith("KEYCODE_")&&f.getInt(null)==k)return f.getName().substring(8);}catch(Exception ignored){}return "Key "+k;}
}
